// Abweichungen finden: vergleicht Papierkram (vollstaendig, nur aktive Kunden und Projekte) mit dem Sync-Gedaechtnis
// und prueft, ob die Kacheln aktiver Kunden und Projekte in timeBuzzer noch aktiv sind.
// Gleiche Regeln wie SYNC 1 (Kunden) und SYNC 2 (Projekte). Nur wenn hier etwas abweicht, wird der Sync gestartet.
const kunden = $('Kunden (PK 2)').first().json.eintraege;
const projekte = $('Projekte (PK 2)').first().json.eintraege;
if (!Array.isArray(kunden) || !Array.isArray(projekte)) throw new Error('Papierkram-Listen fehlen – kein Abgleich.');
const kachelStatus = $('Kachelstatus (TB 1)').first().json.status || {};
const zeilen = $('Sync-Gedächtnis laden').all().map(i => i.json).filter(m => m.entity_type);
const kMap = {}, pMap = {};
for (const m of zeilen) (m.entity_type === 'customer' ? kMap : pMap)[m.papierkram_id] = m;

const kachelText = st => st === 'geloescht' ? 'gelöscht' : 'archiviert';
const abw = [];
const aktiveKunden = kunden.filter(e => e.contact_type === 'customer' && e.record_state === 'active');
const aktiveKundenIds = new Set(aktiveKunden.map(e => String(e.id)));
for (const k of aktiveKunden) {
  const m = kMap[String(k.id)];
  const hash = k.name + '|' + (k.color || '');
  const st = m ? kachelStatus[String(m.timebuzzer_tile_id)] : null;
  if (!m) abw.push('Neuer Kunde: ' + k.name);
  else if (!st) throw new Error('Kachelstatus fehlt für Kunde ' + k.name + ' – kein Abgleich.');
  else if (st !== 'aktiv') abw.push('Kunden-Kachel in timeBuzzer ' + kachelText(st) + ': ' + k.name);
  else if (m.status !== 'active') abw.push('Kunde wieder aktiv: ' + k.name);
  else if (m.last_synced_hash !== hash) abw.push('Kunde geändert: ' + k.name);
}
for (const m of Object.values(kMap)) if (m.status === 'active' && !aktiveKundenIds.has(m.papierkram_id)) abw.push('Kunde nicht mehr aktiv: ' + String(m.last_synced_hash || '').split('|')[0]);

const relevant = projekte.filter(p => p.record_state === 'active' && aktiveKundenIds.has(String(p.company_id)));
const relevantIds = new Set(relevant.map(p => String(p.id)));
for (const p of relevant) {
  const m = pMap[String(p.id)];
  const hash = p.name + '|' + (p.color || '');
  const st = m ? kachelStatus[String(m.timebuzzer_tile_id)] : null;
  if (!m) abw.push('Neues Projekt: ' + p.name);
  else if (!st) throw new Error('Kachelstatus fehlt für Projekt ' + p.name + ' – kein Abgleich.');
  else if (st !== 'aktiv') abw.push('Projekt-Kachel in timeBuzzer ' + kachelText(st) + ': ' + p.name);
  else if (m.status !== 'active') abw.push('Projekt wieder aktiv: ' + p.name);
  else if (String(m.extra_data || '') !== String(p.company_id)) abw.push('Projekt hat anderen Kunden: ' + p.name);
  else if (m.last_synced_hash !== hash) abw.push('Projekt geändert: ' + p.name);
}
for (const m of Object.values(pMap)) if (m.status === 'active' && !relevantIds.has(m.papierkram_id)) abw.push('Projekt nicht mehr aktiv: ' + String(m.last_synced_hash || '').split('|')[0]);

return [{ json: { anzahl: abw.length, abweichungen: abw, trigger: 'ohne_zeiten' } }];

// Kachel-IDs sammeln (SYNC 5): Kacheln aller Zuordnungen aktiver Kunden und aktiver Projekte aktiver Kunden.
// TB 1 prueft danach, ob diese Kacheln in timeBuzzer aktiv, archiviert oder geloescht sind (keine Papierkram-Credits).
const kunden = $('Kunden (PK 2)').first().json.eintraege;
const projekte = $('Projekte (PK 2)').first().json.eintraege;
if (!Array.isArray(kunden) || !Array.isArray(projekte)) throw new Error('Papierkram-Listen fehlen – kein Abgleich.');
const aktiveKunden = new Set(kunden.filter(e => e.contact_type === 'customer' && e.record_state === 'active').map(e => String(e.id)));
const aktiveProjekte = new Set(projekte.filter(p => p.record_state === 'active' && aktiveKunden.has(String(p.company_id))).map(p => String(p.id)));
const ids = $('Sync-Gedächtnis laden').all().map(i => i.json)
  .filter(m => m.entity_type && m.timebuzzer_tile_id && (m.entity_type === 'customer' ? aktiveKunden.has(m.papierkram_id) : aktiveProjekte.has(m.papierkram_id)))
  .map(m => String(m.timebuzzer_tile_id));
return [{ json: { kacheln: ids.join(',') } }];
